1	import { AdditiveBlending, ShaderMaterial } from 'three'
2	
3	/**
4	 * The material every luminous point layer in the deck uses.
5	 *
6	 * Points, not billboarded quads: a point sprite always faces the camera and
7	 * the whole layer is one draw call, which is what keeps 147 pulsing agents and
8	 * a hundred finding markers inside the frame budget. Size and brightness are
9	 * per-point attributes, so a scene animates a typed array rather than a scene
10	 * graph.
11	 * @returns A new additive point material; each layer owns its own instance.
12	 */
13	export function createGlowMaterial(): ShaderMaterial {
14	  return new ShaderMaterial({
15	    transparent: true,
16	    depthWrite: false,
17	    blending: AdditiveBlending,
18	    uniforms: {},
19	    vertexShader: /* glsl */`
20	      attribute float aSize;
21	      attribute vec3 aColor;
22	      attribute float aGain;
23	      varying vec3 vColor;
24	      varying float vGain;
25	      void main() {
26	        vColor = aColor;
27	        vGain = aGain;
28	        vec4 mv = modelViewMatrix * vec4(position, 1.0);
29	        gl_PointSize = aSize * (320.0 / max(-mv.z, 0.001));
30	        gl_Position = projectionMatrix * mv;
31	      }
32	    `,
33	    fragmentShader: /* glsl */`
34	      varying vec3 vColor;
35	      varying float vGain;
36	      void main() {
37	        float d = length(gl_PointCoord - vec2(0.5));
38	        if (d > 0.5) discard;
39	        float core = smoothstep(0.5, 0.06, d);
40	        float halo = smoothstep(0.5, 0.0, d) * 0.45;
41	        gl_FragColor = vec4(vColor * (core + halo), (core + halo) * vGain);
42	      }
43	    `,
44	  })
45	}
46

1	/*
2	 * The deck's visual system: one dark ground, one luminous accent per meaning,
3	 * and type that stays quiet so the scene carries the image.
4	 */
5	
6	:root {
7	  --bg: #04060b;
8	  --bg-2: #070b13;
9	  --panel: rgba(10, 15, 25, 0.78);
10	  --panel-solid: #0a0f19;
11	  --raised: rgba(24, 33, 50, 0.6);
12	  --line: rgba(122, 152, 205, 0.16);
13	  --line-strong: rgba(122, 152, 205, 0.32);
14	
15	  --ink: #e8eefc;
16	  --ink-2: #a2b2ce;
17	  --ink-3: #64749a;
18	
19	  --cyan: #4fd8ff;
20	  --violet: #9b7bff;
21	  --amber: #ffbe5c;
22	  --green: #49e0a6;
23	  --red: #ff3f6b;
24	
25	  --critical: #ff3f6b;
26	  --high: #ff8a3d;
27	  --medium: #ffc94d;
28	  --low: #4fd8ff;
29	  --info: #7f8fb0;
30	
31	  --font-ui: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
32	  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
33	
34	  --header: 52px;
35	  --footer: 30px;
36	  --panel-w: 400px;
37	  --radius: 10px;
38	}
39	
40	* { box-sizing: border-box; }
41	
42	html,
43	body {
44	  margin: 0;
45	  padding: 0;
46	  height: 100%;
47	  overflow: hidden;
48	}
49	
50	body {
51	  background: var(--bg);
52	  color: var(--ink);
53	  font-family: var(--font-ui);
54	  font-size: 13px;
55	  line-height: 1.5;
56	  -webkit-font-smoothing: antialiased;
57	  text-rendering: optimizeLegibility;
58	  font-variant-numeric: tabular-nums;
59	}
60	
61	a { color: inherit; text-decoration: none; }
62	
63	::selection { background: rgba(79, 216, 255, 0.28); }
64	
65	/* Scrollbars: present but never loud. */
66	* { scrollbar-width: thin; scrollbar-color: rgba(122, 152, 205, 0.3) transparent; }
67	*::-webkit-scrollbar { width: 8px; height: 8px; }
68	*::-webkit-scrollbar-thumb { background: rgba(122, 152, 205, 0.22); border-radius: 8px; }
69	*::-webkit-scrollbar-thumb:hover { background: rgba(122, 152, 205, 0.4); }
70	*::-webkit-scrollbar-track { background: transparent; }
71	
72	/* ---------------------------------------------------------------- shell -- */
73	
74	.deck {
75	  display: grid;
76	  grid-template-rows: var(--header) 1fr var(--footer);
77	  height: 100dvh;
78	  background:
79	    radial-gradient(120% 90% at 50% -20%, #0d1524 0%, #05080f 55%, #03050a 100%);
80	}
81	
82	.deck__header {
83	  display: flex;
84	  align-items: center;
85	  gap: 20px;
86	  padding: 0 18px;
87	  border-bottom: 1px solid var(--line);
88	  background: linear-gradient(180deg, rgba(10, 16, 27, 0.92), rgba(6, 10, 18, 0.72));
89	  backdrop-filter: blur(12px);
90	  z-index: 20;
91	}
92	
93	.deck__mark {
94	  display: flex;
95	  align-items: baseline;
96	  gap: 9px;
97	  white-space: nowrap;
98	}
99	
100	.deck__mark b {
101	  font-size: 14px;
102	  font-weight: 600;
103	  letter-spacing: 0.02em;
104	}
105	
106	.deck__mark span {
107	  font-size: 9.5px;
108	  text-transform: uppercase;
109	  letter-spacing: 0.22em;
110	  color: var(--ink-3);
111	}
112	
113	.deck__nav { display: flex; gap: 4px; }
114	
115	.deck__nav a {
116	  position: relative;
117	  display: flex;
118	  align-items: center;
119	  gap: 8px;
120	  height: 30px;
121	  padding: 0 12px;
122	  border-radius: 7px;
123	  font-size: 12px;
124	  color: var(--ink-2);
125	  border: 1px solid transparent;
126	  transition: color 140ms ease, background 140ms ease, border-color 140ms ease;
127	}
128	
129	.deck__nav a:hover { color: var(--ink); background: rgba(79, 216, 255, 0.06); }
130	
131	.deck__nav a[data-active='true'] {
132	  color: var(--ink);
133	  background: rgba(79, 216, 255, 0.1);
134	  border-color: rgba(79, 216, 255, 0.28);
135	  box-shadow: 0 0 22px -8px rgba(79, 216, 255, 0.7) inset;
136	}
137	
138	.deck__nav kbd {
139	  font-family: var(--font-mono);
140	  font-size: 9px;
141	  color: var(--ink-3);
142	  border: 1px solid var(--line);
143	  border-radius: 4px;
144	  padding: 0 4px;
145	  line-height: 14px;
146	}
147	
148	.deck__spacer { flex: 1; }
149	
150	.deck__counts { display: flex; gap: 18px; }
151	
152	.count { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.15; }
153	.count b { font-size: 15px; font-weight: 600; letter-spacing: -0.01em; }
154	.count span { font-size: 9px; text-transform: uppercase; letter-spacing: 0.16em; color: var(--ink-3); }
155	.count[data-tone='active'] b { color: var(--cyan); }
156	.count[data-tone='certified'] b { color: var(--green); }
157	
158	.deck__main { position: relative; overflow: hidden; }
159	
160	.deck__footer {
161	  display: flex;
162	  align-items: center;
163	  gap: 14px;
164	  padding: 0 18px;
165	  border-top: 1px solid var(--line);
166	  background: rgba(5, 8, 14, 0.9);
167	  font-family: var(--font-mono);
168	  font-size: 10.5px;
169	  color: var(--ink-3);
170	  white-space: nowrap;
171	  overflow: hidden;
172	}
173	
174	.deck__footer b { color: var(--ink-2); font-weight: 500; }
175	
176	/* ---------------------------------------------------------------- badge -- */
177	
178	.badge {
179	  display: inline-flex;
180	  align-items: center;
181	  gap: 7px;
182	  height: 24px;
183	  padding: 0 10px;
184	  border-radius: 999px;
185	  font-size: 10px;
186	  text-transform: uppercase;
187	  letter-spacing: 0.16em;
188	  border: 1px solid var(--line-strong);
189	  color: var(--ink-2);
190	}
191	
192	.badge__dot {
193	  width: 6px;
194	  height: 6px;
195	  border-radius: 50%;
196	  background: currentColor;
197	}
198	
199	.badge[data-mode='live'] { color: var(--green); border-color: rgba(73, 224, 166, 0.4); background: rgba(73, 224, 166, 0.08); }
200	.badge[data-mode='replay'] { color: var(--amber); border-color: rgba(255, 190, 92, 0.38); background: rgba(255, 190, 92, 0.07); }
201	.badge[data-mode='probing'] { color: var(--ink-3); }
202	
203	.badge[data-mode='live'] .badge__dot { animation: pulse 2s ease-in-out infinite; }
204	
205	@keyframes pulse {
206	  0%, 100% { opacity: 1; box-shadow: 0 0 0 0 currentColor; }
207	  50% { opacity: 0.55; box-shadow: 0 0 0 4px rgba(73, 224, 166, 0); }
208	}
209	
210	/* ---------------------------------------------------------------- views -- */
211	
212	.view { position: absolute; inset: 0; display: grid; }
213	.view--split { grid-template-columns: 1fr var(--panel-w); }
214	
215	.stage { position: relative; min-width: 0; }
216	.stage canvas { display: block; touch-action: none; }
217	
218	.stage__overlay {
219	  position: absolute;
220	  inset: 0;
221	  pointer-events: none;
222	  padding: 16px;
223	  display: flex;
224	  flex-direction: column;
225	  justify-content: space-between;
226	}
227	
228	.stage__title { max-width: 440px; }
229	.stage__title h1 { margin: 0; font-size: 17px; font-weight: 500; letter-spacing: -0.01em; }
230	.stage__title p { margin: 5px 0 0; font-size: 11.5px; color: var(--ink-3); line-height: 1.5; }
231	
232	.hint {
233	  align-self: flex-start;
234	  font-family: var(--font-mono);
235	  font-size: 10px;
236	  color: var(--ink-3);
237	  border: 1px solid var(--line);
238	  border-radius: 6px;
239	  padding: 4px 8px;
240	  background: rgba(6, 10, 18, 0.6);
241	}
242	
243	/* ---------------------------------------------------------------- panel -- */
244	
245	.panel {
246	  border-left: 1px solid var(--line);
247	  background: linear-gradient(180deg, rgba(9, 14, 23, 0.9), rgba(5, 9, 15, 0.96));
248	  backdrop-filter: blur(14px);
249	  display: flex;
250	  flex-direction: column;
251	  min-height: 0;
252	  overflow: hidden;
253	}
254	
255	.panel__head {
256	  padding: 14px 16px 12px;
257	  border-bottom: 1px solid var(--line);
258	}
259	
260	.panel__eyebrow {
261	  font-size: 9px;
262	  text-transform: uppercase;
263	  letter-spacing: 0.2em;
264	  color: var(--ink-3);
265	}
266	
267	.panel__title { margin: 5px 0 0; font-size: 15px; font-weight: 550; letter-spacing: -0.01em; }
268	.panel__sub { margin: 3px 0 0; font-size: 11.5px; color: var(--ink-2); }
269	
270	.panel__body { flex: 1; min-height: 0; overflow-y: auto; padding: 14px 16px 24px; }
271	
272	.panel__empty {
273	  display: flex;
274	  flex-direction: column;
275	  gap: 6px;
276	  padding: 26px 16px;
277	  color: var(--ink-3);
278	  font-size: 12px;
279	}
280	
281	.field { display: grid; grid-template-columns: 96px 1fr; gap: 8px; padding: 5px 0; align-items: baseline; }
282	.field dt { font-size: 10px; text-transform: uppercase; letter-spacing: 0.14em; color: var(--ink-3); }
283	.field dd { margin: 0; font-size: 12px; color: var(--ink); word-break: break-word; }
284	.field dd.mono { font-family: var(--font-mono); font-size: 11px; color: var(--ink-2); }
285	
286	.section { margin-top: 18px; }
287	.section > h3 {
288	  margin: 0 0 8px;
289	  font-size: 9.5px;
290	  text-transform: uppercase;
291	  letter-spacing: 0.2em;
292	  color: var(--ink-3);
293	  font-weight: 600;
294	}
295	
296	.chips { display: flex; flex-wrap: wrap; gap: 5px; }
297	
298	.chip {
299	  font-family: var(--font-mono);
300	  font-size: 10.5px;
301	  color: var(--ink-2);
302	  border: 1px solid var(--line);
303	  background: rgba(122, 152, 205, 0.06);
304	  border-radius: 5px;
305	  padding: 2px 7px;
306	}
307	
308	.chip[data-tone='tool'] { color: var(--cyan); border-color: rgba(79, 216, 255, 0.25); }
309	.chip[data-tone='skill'] { color: var(--violet); border-color: rgba(155, 123, 255, 0.25); }
310	
311	.status-tag {
312	  display: inline-flex;
313	  align-items: center;
314	  gap: 6px;
315	  font-size: 10px;
316	  text-transform: uppercase;
317	  letter-spacing: 0.14em;
318	}
319	
320	.status-tag::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
321	.status-tag[data-status='defined'] { color: var(--ink-3); }
322	.status-tag[data-status='active'] { color: var(--cyan); }
323	.status-tag[data-status='certified'] { color: var(--green); }
324	.status-tag[data-status='failed'] { color: var(--red); }
325	
326	/* ----------------------------------------------------------- event feed -- */
327	
328	.feed { display: flex; flex-direction: column; gap: 1px; }
329	
330	.feed__row {
331	  display: grid;
332	  grid-template-columns: 56px 1fr;
333	  gap: 9px;
334	  padding: 5px 7px;
335	  border-radius: 6px;
336	  font-size: 11.5px;
337	  border-left: 2px solid transparent;
338	  background: rgba(122, 152, 205, 0.03);
339	}
340	
341	.feed__row time { font-family: var(--font-mono); font-size: 10px; color: var(--ink-3); }
342	.feed__label { color: var(--ink); }
343	.feed__detail { color: var(--ink-3); font-size: 10.5px; margin-top: 1px; }
344	.feed__who { color: var(--ink-3); font-size: 10px; font-family: var(--font-mono); }
345	
346	.feed__row[data-kind='finding'] { border-left-color: var(--critical); }
347	.feed__row[data-kind='certificate'] { border-left-color: var(--green); }
348	.feed__row[data-kind='delegation'] { border-left-color: var(--violet); }
349	.feed__row[data-kind='directive'] { border-left-color: var(--amber); }
350	.feed__row[data-kind='merge'] { border-left-color: var(--cyan); }
351	.feed__row[data-kind='refusal'] { border-left-color: var(--red); }
352	.feed__row[data-kind='tool'] { border-left-color: rgba(122, 152, 205, 0.3); }
353	
354	/* -------------------------------------------------------------- controls -- */
355	
356	.control-bar {
357	  display: flex;
358	  align-items: center;
359	  gap: 10px;
360	  padding: 9px 14px;
361	  border-top: 1px solid var(--line);
362	  background: rgba(6, 10, 18, 0.92);
363	  pointer-events: auto;
364	}
365	
366	button.btn,
367	a.btn {
368	  appearance: none;
369	  border: 1px solid var(--line-strong);
370	  background: rgba(122, 152, 205, 0.07);
371	  color: var(--ink);
372	  font-family: inherit;
373	  font-size: 11.5px;
374	  border-radius: 7px;
375	  padding: 6px 12px;
376	  cursor: pointer;
377	  transition: background 140ms ease, border-color 140ms ease, color 140ms ease;
378	}
379	
380	button.btn:hover,
381	a.btn:hover { background: rgba(79, 216, 255, 0.12); border-color: rgba(79, 216, 255, 0.4); }
382	button.btn:disabled { opacity: 0.45; cursor: not-allowed; }
383	button.btn[data-variant='primary'] { background: rgba(79, 216, 255, 0.16); border-color: rgba(79, 216, 255, 0.45); color: #d8f6ff; }
384	
385	select.input,
386	input.input {
387	  appearance: none;
388	  width: 100%;
389	  border: 1px solid var(--line);
390	  background: rgba(6, 10, 18, 0.8);
391	  color: var(--ink);
392	  font-family: var(--font-mono);
393	  font-size: 11.5px;
394	  border-radius: 7px;
395	  padding: 6px 9px;
396	  outline: none;
397	}
398	
399	select.input:focus,
400	input.input:focus { border-color: rgba(79, 216, 255, 0.5); }
401	
402	label.label {
403	  display: block;
404	  font-size: 9.5px;
405	  text-transform: uppercase;
406	  letter-spacing: 0.16em;
407	  color: var(--ink-3);
408	  margin-bottom: 5px;
409	}
410	
411	input[type='range'] {
412	  appearance: none;
413	  width: 100%;
414	  height: 3px;
415	  border-radius: 3px;
416	  background: linear-gradient(90deg, var(--cyan) var(--fill, 0%), rgba(122, 152, 205, 0.2) var(--fill, 0%));
417	  outline: none;
418	  cursor: pointer;
419	}
420	
421	input[type='range']::-webkit-slider-thumb {
422	  appearance: none;
423	  width: 12px;
424	  height: 12px;
425	  border-radius: 50%;
426	  background: #d8f6ff;
427	  border: 1px solid rgba(79, 216, 255, 0.8);
428	  box-shadow: 0 0 12px rgba(79, 216, 255, 0.6);
429	}
430	
431	input[type='range']::-moz-range-thumb {
432	  width: 12px;
433	  height: 12px;
434	  border-radius: 50%;
435	  background: #d8f6ff;
436	  border: 1px solid rgba(79, 216, 255, 0.8);
437	}
438	
439	/* -------------------------------------------------------------- tables --- */
440	
441	.table { width: 100%; border-collapse: collapse; font-size: 11.5px; }
442	.table th {
443	  text-align: left;
444	  font-size: 9px;
445	  text-transform: uppercase;
446	  letter-spacing: 0.16em;
447	  color: var(--ink-3);
448	  font-weight: 600;
449	  padding: 0 6px 7px;
450	  position: sticky;
451	  top: 0;
452	  background: var(--panel-solid);
453	  z-index: 1;
454	}
455	.table td { padding: 6px; border-top: 1px solid rgba(122, 152, 205, 0.09); vertical-align: top; overflow-wrap: anywhere; }
456	.table tbody tr { cursor: pointer; }
457	.table tbody tr:hover td { background: rgba(122, 152, 205, 0.06); }
458	.table tbody tr[data-selected='true'] td { background: rgba(79, 216, 255, 0.1); }
459	.table .mono { font-family: var(--font-mono); font-size: 10.5px; color: var(--ink-2); }
460	
461	.sev {
462	  display: inline-flex;
463	  align-items: center;
464	  gap: 5px;
465	  font-size: 9.5px;
466	  text-transform: uppercase;
467	  letter-spacing: 0.12em;
468	}
469	.sev::before { content: ''; width: 7px; height: 7px; border-radius: 2px; background: currentColor; }
470	.sev[data-s='critical'] { color: var(--critical); }
471	.sev[data-s='high'] { color: var(--high); }
472	.sev[data-s='medium'] { color: var(--medium); }
473	.sev[data-s='low'] { color: var(--low); }
474	.sev[data-s='info'] { color: var(--info); }
475	
476	/* ---------------------------------------------------------------- cards -- */
477	
478	.card {
479	  border: 1px solid var(--line);
480	  border-radius: var(--radius);
481	  background: rgba(122, 152, 205, 0.04);
482	  padding: 12px 13px;
483	}
484	
485	.card--verified { border-color: rgba(73, 224, 166, 0.32); background: rgba(73, 224, 166, 0.05); }
486	
487	.card__head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
488	.card__head h4 { margin: 0; font-size: 12.5px; font-weight: 550; }
489	
490	.tally { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; margin-top: 11px; }
491	.tally > div { text-align: center; border: 1px solid var(--line); border-radius: 7px; padding: 6px 2px; }
492	.tally b { display: block; font-size: 15px; font-weight: 600; line-height: 1.1; }
493	.tally span { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.1em; color: var(--ink-3); }
494	
495	.snippet {
496	  font-family: var(--font-mono);
497	  font-size: 10.5px;
498	  line-height: 1.6;
499	  color: #cfe3ff;
500	  background: rgba(3, 6, 12, 0.85);
501	  border: 1px solid var(--line);
502	  border-left: 2px solid var(--critical);
503	  border-radius: 7px;
504	  padding: 9px 11px;
505	  overflow-x: auto;
506	  white-space: pre-wrap;
507	  word-break: break-word;
508	  margin: 0;
509	}
510	
511	.tabs { display: flex; gap: 3px; padding: 10px 16px 0; border-bottom: 1px solid var(--line); }
512	
513	.tabs button {
514	  appearance: none;
515	  background: none;
516	  border: none;
517	  border-bottom: 2px solid transparent;
518	  color: var(--ink-3);
519	  font-family: inherit;
520	  font-size: 11px;
521	  text-transform: uppercase;
522	  letter-spacing: 0.14em;
523	  padding: 5px 9px 8px;
524	  cursor: pointer;
525	}
526	
527	.tabs button[data-active='true'] { color: var(--ink); border-bottom-color: var(--cyan); }
528	
529	.filters { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
530	
531	/* ------------------------------------------------------- finding detail -- */
532	
533	.finding-card {
534	  position: absolute;
535	  left: 16px;
536	  bottom: 16px;
537	  width: min(480px, calc(100% - 32px));
538	  max-height: calc(100% - 150px);
539	  overflow-y: auto;
540	  pointer-events: auto;
541	  border: 1px solid var(--line-strong);
542	  border-radius: 12px;
543	  background: linear-gradient(180deg, rgba(10, 15, 26, 0.96), rgba(6, 10, 18, 0.97));
544	  box-shadow: 0 24px 60px -20px rgba(0, 0, 0, 0.9), 0 0 0 1px rgba(79, 216, 255, 0.05);
