/** TEMPORARY dev-only frame-time probe; removed before commit. */
export function FrameProbe({ tag }: { tag: string }): ReactNode {
  const samples = useRef<number[]>([])
  const last = useRef(0)
  const windows = useRef(0)

  useFrame(() => {
    const now = performance.now()
    const previous = last.current
    last.current = now
    if (previous === 0) return
    samples.current.push(now - previous)
    if (samples.current.length < 180) return
    const sorted = [...samples.current].sort((a, b) => a - b)
    const mean = samples.current.reduce((sum, value) => sum + value, 0) / samples.current.length
    const p95 = sorted[Math.floor(sorted.length * 0.95)] ?? 0
    samples.current = []
    windows.current += 1
    // eslint-disable-next-line no-console
    console.log(`FRAMEPROBE ${tag} window=${windows.current} mean=${mean.toFixed(2)}ms p95=${p95.toFixed(2)}ms fps=${(1000 / mean).toFixed(1)}`)
  })

  return null
}

