export interface Flight {
  /** The stage the event was logged at. */
  stage: number
  /** Lane position for departmental work, `-1` for anything later in the pipeline. */
  lane: number
  /** Scene x the comet leaves from. */
  fromX: number
  /** Scene x of the gate the comet arrives at. */
  toX: number
