/*
 * Labels drawn over the pipeline.
 *
 * They ride in the scene through drei's `Html`, so they are DOM at screen
 * resolution rather than textures: the type stays crisp on a boardroom screen
 * at any camera distance. Nothing here wraps, and nothing here is wider than
 * its own content, so a label cannot clip against a gate or a rail.
 */

.gate {
  white-space: nowrap;
  pointer-events: none;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: #e9f2ff;
  text-shadow:
    0 0 4px rgba(4, 6, 11, 1),
    0 0 18px rgba(4, 6, 11, 0.95);
}

.gate::after {
  content: '';
  display: block;
  height: 1px;
  margin-top: 5px;
  background: linear-gradient(90deg, transparent, currentColor, transparent);
  opacity: 0.55;
}

.lane {
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
  pointer-events: none;
  font-size: 10.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #8ea2c6;
  text-shadow: 0 0 10px rgba(4, 6, 11, 0.95);
}

.lane[data-lit='true'] { color: #eaf3ff; }

.laneDot {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 2px;
  background: currentColor;
  box-shadow: 0 0 0 rgba(0, 0, 0, 0);
}

.lane[data-lit='true'] .laneDot { box-shadow: 0 0 12px 1px currentColor; }

.laneCount {
  font-family: var(--font-mono);
  font-size: 9.5px;
  letter-spacing: 0.06em;
  color: #5f708f;
}

.lane[data-lit='true'] .laneCount { color: #a9bddf; }

.laneIdle { opacity: 0.45; }

