7	 * animate through uniforms rather than through React. None writes depth, so the
8	 * layer order alone decides what reads in front of what.
9	 */
10	
11	import { AdditiveBlending, Color, DoubleSide, ShaderMaterial, type IUniform } from 'three'
12	
13	/** A material whose brightness the scene rewrites every frame. */
14	export interface DimmedMaterial {
15	  material: ShaderMaterial
16	  /** The `uGain` uniform, held directly so the frame loop never looks it up. */
17	  gain: IUniform<number>
18	}
