20	/**
21	 * The comet trail material: one camera-facing ribbon per flight.
22	 *
23	 * The ribbon is widened in view space, so a trail keeps its thickness whatever
24	 * angle the camera holds and no geometry has to be rebuilt when it turns.
25	 * `aTangent` is the path direction at the vertex, `aSide` which of the ribbon's
26	 * two edges the vertex is, and `aGain` how bright that point of the trail is.
27	 * @returns A new trail material; each layer owns its own instance.
28	 */
29	export function createTrailMaterial(): ShaderMaterial {
30	  return new ShaderMaterial({
31	    transparent: true,
32	    depthWrite: false,
33	    blending: AdditiveBlending,
34	    side: DoubleSide,
35	    uniforms: {},
36	    vertexShader: /* glsl */`
37	      attribute vec3 aTangent;
38	      attribute float aSide;
39	      attribute float aWidth;
40	      attribute vec3 aColor;
41	      attribute float aGain;
42	      varying vec3 vColor;
43	      varying float vGain;
44	      varying float vSide;
45	      void main() {
